INSERT INTO public.questions (
  id, subject_id, chapter_id, topic_tag, bank_pool, question_type, difficulty_tier, exam_year_tag,
  q_hi, q_en, options_json, correct_option, clue_hi, clue_en, explanation_hi, explanation_en,
